export function isLocalePreference(value: string | null | undefined): value is LocalePreference {
  return localePreferences.includes(value as LocalePreference);
}

export function resolveSystemLocale(deviceLanguageTags: readonly (string | null | undefined)[]): AppLocale {
  for (const deviceLanguageTag of deviceLanguageTags) {
    const tag = (deviceLanguageTag || "").replaceAll("_", "-");
    const normalized = tag.toLowerCase();
    if (normalized.startsWith("en")) return "en";
    if (normalized.startsWith("zh")) {
      if (normalized.includes("hant") || /-(tw|hk|mo)(-|$)/.test(normalized)) return "zh-Hant";
      return "zh-Hans";
    }
  }
  return defaultAppLocale;
}

export function resolveAppLocale(
  preference: LocalePreference,
  deviceLanguageTags: string | null | undefined | readonly (string | null | undefined)[],
): AppLocale {
  if (preference !== "system") return preference;
  return resolveSystemLocale(Array.isArray(deviceLanguageTags) ? deviceLanguageTags : [deviceLanguageTags]);
}

export function createI18n(locale: AppLocale) {
  const i18n = new I18n(translations);
  i18n.defaultLocale = defaultAppLocale;
  i18n.enableFallback = true;
  i18n.locale = locale;
  return i18n;
}

export function translate(locale: AppLocale, key: string, options?: TranslateOptions) {
  return createI18n(locale).t(key, options);
}

export function formatLocalizedDate(locale: AppLocale, value: string | number | Date) {
  return new Intl.DateTimeFormat(locale, {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(value));
}
